SELECT distinct bk.task_id ,bk.dept_id ,bk.dept_name ,bk.store_id ,bk.store_name ,bk.applicant ,bk.applicant_id ,bk.applicant_name ,bk.task_type ,bk.handle_dept_id ,bk.handle_dept_name ,bk.flow_id ,bk.flow_name ,bk.task_name ,bk.store_type ,bk.priority ,bk.completion_time ,bk.task_completion_time ,bk.task_desc ,bk.proc_inst_id ,bk.file_urls ,bk.parent_proc_inst_id ,bk.business_id ,bk.creator ,bk.create_time ,bk.updater ,bk.update_time ,bk.deleted ,bk.task_state ,bk.business_key ,bk.executor_user_id ,bk.executor_dept_id ,bk.executor_user_name ,bk.executor_dept_name ,IFNULL(bty.copy_flag, 0) AS copy_flag ,bk.icon_url ,bk.oa_project_id FROM business_task bk left join business_task_copy bty on ( bk.proc_inst_id = bty.proc_inst_id and bty.copy_user_id = #{userId} ) where bk.deleted = b'0'
AND bk.proc_inst_id IN
#{procInstId}
AND bk.applicant_id = #{queryVO.applicantId}
AND ( bk.task_name like CONCAT('%', #{queryVO.taskContent}, '%') or bk.task_desc like CONCAT('%', #{queryVO.taskContent}, '%') )
AND bk.applicant_id IN
#{applicantId}
AND bk.priority = #{queryVO.priority}
AND bk.DEPT_ID IN
#{deptId}
AND bk.store_id = #{queryVO.applicantStoreId}
AND bk.flow_id = #{queryVO.processDefinitionId}
AND bk.task_state != 6 AND bk.task_state != 4 AND sysdate() > bk.completion_time
AND bk.task_state = #{queryVO.taskState}
AND bk.task_type = #{queryVO.taskType}
AND bty.copy_flag = #{queryVO.copyFlag}
AND bk.oa_project_id = #{queryVO.oaProjectId}
